        self.assertEqual(cd.get("format"), "date", "data.closed_date PHẢI format date.")
        self.assertNotIn("nullable", cd, "data.closed_date KHÔNG nullable (today() set UNCONDITIONAL @imm12.py:555 — KHÁC resolve rca_created).")
