        self.assertEqual(slab.get("enum"), [0, 1], "data.sla_breached.enum PHẢI [0,1].")
        self.assertEqual(slab.get("nullable"), True, "data.sla_breached PHẢI nullable (cannot_repair branch KHÔNG có).")
