        self.assertNotEqual(_ADD_MEASUREMENT_RESPONSE_SCHEMA, _START_REPAIR_ACTION_RESPONSE_SCHEMA, "PHẢI schema RIÊNG (KHÔNG reuse RepairActionResponse).")

